// slam_refact::libcxx must reproduce emsdk 5.0.0 libc++ results bit for bit
// (architecture.md §5.2-5.3, WP0a acceptance "compat golden 일치"), except sort, which follows
// libc++ 14 like the original binary (third_party/libcxx_compat/.../sort_llvm14.h).
//
// The golden files are generated by gen_libcxx_golden --impl=std built with em++ 5.0.0
// (libcxx-golden.json) and natively against libc++ 14 for the sort/ cases
// (libcxx14-sort-golden.json, tools/gen_libcxx14_sort_golden.sh); see tests/data/MANIFEST.tsv.
#include <cstdint>
#include <cstdlib>
#include <fstream>
#include <map>
#include <regex>
#include <string>
#include <vector>

#include "gtest/gtest.h"
#include "libcxx_golden_cases.h"
#include "libcxx_golden_impls.h"

#ifndef SR_TEST_DATA_DIR
#error "SR_TEST_DATA_DIR must point at slam_refact/engine/tests/data"
#endif

namespace slam_refact {
namespace golden {
namespace {

std::map<std::string, std::string> LoadGolden(const std::string& path, std::string* impl, int* case_count) {
  std::ifstream in(path);
  std::map<std::string, std::string> out;
  if (!in) return out;
  const std::regex case_re("\\{\"name\": \"([^\"]+)\", \"digest\": \"([0-9a-f]{16})\"\\}");
  const std::regex impl_re("\"impl\": \"([a-z]+)\"");
  const std::regex count_re("\"case_count\": ([0-9]+)");
  std::string line;
  std::smatch m;
  while (std::getline(in, line)) {
    if (std::regex_search(line, m, case_re)) {
      out[m[1].str()] = m[2].str();
    } else if (std::regex_search(line, m, impl_re)) {
      *impl = m[1].str();
    } else if (std::regex_search(line, m, count_re)) {
      *case_count = std::atoi(m[1].str().c_str());
    }
  }
  return out;
}

std::string Hex(uint64_t v) {
  char buf[17];
  std::snprintf(buf, sizeof(buf), "%016llx", static_cast<unsigned long long>(v));
  return buf;
}

TEST(LibcxxCompatGolden, MatchesEmsdkLibcxx) {
  std::string impl;
  int case_count = -1;
  const std::string path = std::string(SR_TEST_DATA_DIR) + "/compat/libcxx-golden.json";
  const std::map<std::string, std::string> golden = LoadGolden(path, &impl, &case_count);
  ASSERT_FALSE(golden.empty()) << "cannot read " << path;
  ASSERT_EQ(impl, "std") << "golden must be generated from the standard library (libc++), not compat";
  ASSERT_EQ(static_cast<int>(golden.size()), case_count);

  const std::vector<Case> cases = RunGoldenCases<CompatImpl>();
  ASSERT_EQ(cases.size(), golden.size());
  int mismatches = 0;
  for (const Case& c : cases) {
    const auto it = golden.find(c.name);
    ASSERT_NE(it, golden.end()) << "case missing from golden: " << c.name;
    if (c.name.rfind("sort/", 0) == 0) {
      continue;  // libc++ 14 sort: SortMatchesLibcxx14
    }
    if (it->second != Hex(c.digest)) {
      ++mismatches;
      ADD_FAILURE() << c.name << ": compat " << Hex(c.digest) << " != libc++ " << it->second;
    }
  }
  EXPECT_EQ(mismatches, 0);
}

// sort follows libc++ 14 (the original binary's introsort, f1555), not the emsdk 5.0.0 pdq sort.
TEST(LibcxxCompatGolden, SortMatchesLibcxx14) {
  std::string impl;
  int case_count = -1;
  const std::string path = std::string(SR_TEST_DATA_DIR) + "/compat/libcxx14-sort-golden.json";
  const std::map<std::string, std::string> golden = LoadGolden(path, &impl, &case_count);
  ASSERT_FALSE(golden.empty()) << "cannot read " << path;
  ASSERT_EQ(impl, "std");
  ASSERT_EQ(static_cast<int>(golden.size()), case_count);
  int checked = 0;
  int mismatches = 0;
  for (const Case& c : RunGoldenCases<CompatImpl>()) {
    if (c.name.rfind("sort/", 0) != 0) {
      continue;
    }
    ++checked;
    const auto it = golden.find(c.name);
    ASSERT_NE(it, golden.end()) << "case missing from libc++ 14 sort golden: " << c.name;
    if (it->second != Hex(c.digest)) {
      ++mismatches;
      ADD_FAILURE() << c.name << ": compat " << Hex(c.digest) << " != libc++ 14 " << it->second;
    }
  }
  EXPECT_EQ(checked, case_count);
  EXPECT_EQ(mismatches, 0);
}

// The golden set must be able to tell libc++ from another standard library; otherwise matching
// it proves nothing. Only meaningful when the host standard library is not libc++.
TEST(LibcxxCompatGolden, GoldenDiscriminatesHostStandardLibrary) {
#if defined(_LIBCPP_VERSION)
  GTEST_SUCCEED() << "host standard library is libc++; discrimination check not applicable";
#else
  std::string impl;
  int case_count = -1;
  const std::map<std::string, std::string> golden =
      LoadGolden(std::string(SR_TEST_DATA_DIR) + "/compat/libcxx-golden.json", &impl, &case_count);
  ASSERT_FALSE(golden.empty());
  const std::vector<Case> host = RunGoldenCases<StdImpl>();
  int differing = 0;
  for (const Case& c : host) {
    const auto it = golden.find(c.name);
    if (it != golden.end() && it->second != Hex(c.digest)) ++differing;
  }
  EXPECT_GT(differing, 0) << "host std:: results equal libc++ on every case; golden set is not discriminating";
#endif
}

}  // namespace
}  // namespace golden
}  // namespace slam_refact
